import React from 'react';
import './MenuForms.css';

const MenuForms = ({ userId }) => {
    const scrollToInfo = (section) => {
        const infoSection = document.getElementById(section);
        if (infoSection) {
            infoSection.scrollIntoView({ behavior: 'smooth' });
        }
    };

    return (
        <div className="menu-form">
            <h2>¿En qué puede ayudarte FinanTec?</h2>
            <div className="menu-options">
                <div className="saving-box green" onClick={() => scrollToInfo('generar-ahorro')}>
                    <div className="icon">💰</div>
                    <span>Generar Ahorro</span>
                </div>
                <div className="saving-box blue" onClick={() => scrollToInfo('plan-jubilacion')}>
                    <div className="icon">🏦</div>
                    <span>Plan de Jubilación</span>
                </div>
                <div className="saving-box pink" onClick={() => scrollToInfo('metas')}>
                    <div className="icon">🎯</div>
                    <span>Metas Largo/Corto Plazo</span>
                </div>
            </div>

            {/* Sección de información */}
            <div id="info-section" className="info-section">
                <div id="generar-ahorro" className="info-subsection">
                    <h3>Información sobre Generar Ahorro</h3>
                    <p>Aquí puedes encontrar información útil sobre cómo generar ahorros efectivos...</p>
                    <p>Considera establecer metas específicas de ahorro y utilizar herramientas de presupuesto para monitorear tu progreso.</p>
                </div>
                <div id="plan-jubilacion" className="info-subsection">
                    <h3>Información sobre Plan de Jubilación</h3>
                    <p>Un plan de jubilación es esencial para asegurar tu futuro financiero. Aquí aprenderás sobre las diferentes opciones de inversión y cómo elegir la mejor para ti.</p>
                    <p>Evalúa tus necesidades futuras y considera hablar con un asesor financiero para obtener orientación personalizada.</p>
                </div>
                <div id="metas" className="info-subsection">
                    <h3>Información sobre Metas Largo/Corto Plazo</h3>
                    <p>Definir metas a corto y largo plazo te ayudará a mantenerte enfocado en tus objetivos financieros. Asegúrate de tener metas realistas y medibles.</p>
                    <p>Utiliza la regla SMART para establecer tus metas: específicas, medibles, alcanzables, relevantes y con un tiempo determinado.</p>
                </div>
            </div>
        </div>
    );
};

export default MenuForms;
